import{_ as a,a0 as l,w as s,s as u,I as o,x as e,a1 as n,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"試試這個 Linux 網絡瀏覽器作為你的文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"試試這個 Linux 網絡瀏覽器作為你的文件管理器 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"試試這個 Linux 網絡瀏覽器作為你的文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"試試這個 Linux 網絡瀏覽器作為你的文件管理器 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager","title":"試試這個 Linux 網絡瀏覽器作為你的文件管理器","tag":"202212","desc":""},"relativePath":"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager.md","filePath":"[post].md"}'),d={name:"202212/20221213.6 ⭐️⭐️ Try this Linux web browser as your file manager.md"};function m(b,r,h,g,f,k){const t=l("Link");return s(),u("div",null,[r[20]||(r[20]=o("h1",{id:"試試這個-linux-網絡瀏覽器作為你的文件管理器",tabindex:"-1"},[e("試試這個 Linux 網絡瀏覽器作為你的文件管理器 "),o("a",{class:"header-anchor",href:"#試試這個-linux-網絡瀏覽器作為你的文件管理器","aria-label":"Permalink to “試試這個 Linux 網絡瀏覽器作為你的文件管理器”"},"​")],-1)),r[21]||(r[21]=o("p",null,[o("img",{src:"https://img.linux.net.cn/data/attachment/album/202212/29/141332adtz8mb8m8h8z3d4.jpg",alt:""})],-1)),r[22]||(r[22]=o("blockquote",null,[o("p",null,"KDE Plasma 桌面將 Konqueror 列為網絡瀏覽器，但它也是一個功能性的 Linux 文件管理器。")],-1)),r[23]||(r[23]=o("p",null,"Konqueror 是 KDE Plasma 桌面的文件管理器和 Web 瀏覽器。在許多方面，Konqueror 定義了“網絡透明度”，因為它適用於個人桌面。使用 Konqueror，你可以像瀏覽本地文件一樣輕鬆地瀏覽遠程網絡文件（包括互聯網本身，它實際上只是通過花哨的鏡頭查看的遠程文件的集合）。有時需要進行一些配置和設置，具體取決於你需要訪問的文件共享類型。但最終，通過 Konqueror 實現了即時訪問你有權查看的所有數據的目標，這是其他文件管理器無法實現的。在其巔峯時期，它開發的開源網絡引擎（KHTML） 被蘋果和谷歌採用，並作為現代網絡瀏覽和 Electron 應用開發的核心庫延續至今。",-1)),o("p",null,[r[2]||(r[2]=e("今天，KDE Plasma 桌面將 Konqueror 作為網絡瀏覽器。文件管理功能已正式轉移到 ",-1)),n(t,{href:"https://opensource.com/article/22/12/linux-file-manager-dolphin"},{default:i(()=>[...r[0]||(r[0]=[e("Dolphin",-1)])]),_:1}),r[3]||(r[3]=e("，但 Konqueror 仍然能夠完成這項工作。要獲得完整和經典的 Konqueror 體驗，你應該嘗試 Plasma 桌面 3.x 的復刻 ",-1)),n(t,{href:"https://opensource.com/article/19/12/linux-trinity-desktop-environment-tde"},{default:i(()=>[...r[1]||(r[1]=[e("TDE",-1)])]),_:1}),r[4]||(r[4]=e("，但在本文中，我在 KDE Plasma 桌面版本 5 中使用 Konqueror。",-1))]),r[24]||(r[24]=p('<h3 id="安裝-konqueror" tabindex="-1">安裝 Konqueror <a class="header-anchor" href="#安裝-konqueror" aria-label="Permalink to “安裝 Konqueror”">​</a></h3><p>如果你已經在運行 KDE Plasma 桌面，你可能已經安裝了 Konqueror。如果沒有，你可以從發行版軟件倉庫中安裝它。在 Fedora、CentOS、Mageia、OpenMandriva 和類似軟件上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y konqueror konqueror-plugins</span></span></code></pre></div><p>在 Debian、Linux Mint、Elementary 和類似軟件上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y konqueror konqueror-plugins</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-filemanager.png" alt="Image of Konqueror&#39;s file manager."></p><h3 id="將-konqueror-配置為文件管理器" tabindex="-1">將 Konqueror 配置為文件管理器 <a class="header-anchor" href="#將-konqueror-配置為文件管理器" aria-label="Permalink to “將 Konqueror 配置為文件管理器”">​</a></h3><p>Konqueror 最方便的功能是它除了是一個文件管理器之外，還是一個網絡瀏覽器。至少，這在理論上是它最方便的功能。如果你沒有將 Konqueror 用作網絡瀏覽器，那麼你可能不希望每個文件管理器窗口頂部都有 URL 區域或搜索引擎區域。</p><p>與大多數 KDE 應用一樣，Konqueror 是高度可配置的。你可以重新定位並添加和刪除工具欄、添加或刪除按鈕等。</p><p>要調整顯示的工具欄，請啓動 Konqueror 並轉到 “<ruby>設置<rt>Settings</rt></ruby>” 菜單並選擇 “<ruby>顯示的工具欄<rt>Toolbars Shown</rt></ruby>”。主工具欄可能是你真正需要的文件管理工具欄。它是帶有導航按鈕的工具欄。但是，你甚至可能不需要它，只要你樂於使用鍵盤快捷鍵或使用 “Go” 菜單進行導航即可。</p><p>Konqueror 中的鍵盤導航與 Dolphin 中的相同：</p><ul><li><code>Alt + ←</code>：後退一步</li><li><code>Alt + ↑</code>：移動到父目錄</li><li><code>Alt + Home</code>：轉到主目錄</li></ul><h3 id="側邊欄" tabindex="-1">側邊欄 <a class="header-anchor" href="#側邊欄" aria-label="Permalink to “側邊欄”">​</a></h3><p>要獲得包含常用文件夾列表的側邊欄，請按 <code>F9</code> 或從 “<ruby>設置<rt>Settings</rt></ruby>” 菜單中選擇 “<ruby>顯示邊欄<rt>Show Sidebar</rt></ruby>”。這會在 Konqueror 窗口的左側添加一個按鈕欄。單擊 “Home” 圖標以顯示你的主目錄的文件樹。</p><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-sidebar.png" alt="Image of Konqueror with a sidebar."></p><p>正如按鈕欄所暗示的那樣，此側邊欄可用於多種用途。你可以顯示書籤位置，你最近訪問過的位置的歷史，遠程文件系統等。</p><h3 id="應用" tabindex="-1">應用 <a class="header-anchor" href="#應用" aria-label="Permalink to “應用”">​</a></h3><p>有些人習慣於應用菜單。它高效快捷，並且始終在同一個地方。其他人更喜歡從終端啓動應用。</p><p>不過，還有另一種查看應用啓動器的方法。Konqueror 的 “Go” 菜單允許你轉到名為 “<ruby>應用程序<rt>Applications</rt></ruby>” 的元位置，它按類別列出了應用程序啓動器，就像文件管理器中的文件一樣。</p><p><img src="https://opensource.com/sites/default/files/2022-10/konqueror-applications.png" alt="Image of applications in Konqueror."></p><p>你也可以在 Dolphin 中看到這個，方法是在位置區域中手動輸入 <code>applications:</code>，此外，Konqueror 提供了一個菜單選項，可以直接進入該位置。</p><h3 id="網絡文件夾" tabindex="-1">網絡文件夾 <a class="header-anchor" href="#網絡文件夾" aria-label="Permalink to “網絡文件夾”">​</a></h3><p>類似地，Konqueror 還提供了一個菜單選擇進入網絡文件夾。其中最好的網絡文件夾是“互聯網”，但“網絡文件夾”是 HTTP 以外的網絡協議的元位置。大多數遠程位置需要一些設置，因為它們通常需要身份驗證才能訪問。它們中的大多數都可以通過 “<ruby>系統設置<rt>System Settings</rt></ruby>” 進行配置，包括可通過藍牙、SMB 或 CIFS、MTP 設備、Fish（通過 SSH 的文件系統）訪問的文件系統，甚至是 Google Drive。</p><h3 id="拆分視圖" tabindex="-1">拆分視圖 <a class="header-anchor" href="#拆分視圖" aria-label="Permalink to “拆分視圖”">​</a></h3><p>你可以將 Konqueror 窗口拆分為多個窗格，這樣你就可以同時查看兩個文件夾而無需打開兩個窗口。有兩種拆分選項：垂直拆分，一個窗格在左側，另一個窗格在右側；或者水平拆分，一個窗格在另一個窗格之上。</p><p>要分割 Konqueror 窗口，進入 “<ruby>窗口<rt>Window</rt></ruby>” 菜單，選擇 “<ruby>左/右分割視圖<rt>Split View Left/Right</rt></ruby>” 或 “<ruby>上/下分割視圖<rt>Spit View Top/Bottom</rt></ruby>”。每個窗格都是獨立的，所以你可以在一個窗格中瀏覽，然後把文件從一個窗格拖到另一個窗格。</p><h3 id="征服你的文件系統" tabindex="-1">征服你的文件系統 <a class="header-anchor" href="#征服你的文件系統" aria-label="Permalink to “征服你的文件系統”">​</a></h3><p>Konqueror 不 <em>僅僅</em> 是一個文件管理器，我認為 Plasma 桌面的開發者並不期望你把它作為你的主要文件管理器。在 “<ruby>文件<rt>File</rt></ruby>” 菜單中甚至有一個選項可以在 <strong>Dolphin</strong> 中打開一個位置，這表明 Konqueror 是一個帶有文件管理器組件的網絡瀏覽器。但是，當你需要時，這個文件管理器組件是一個不錯的功能。如果你不喜歡 Dolphin 提供的所有功能，Konqueror 可能是一個合適的替代品。</p><hr>',29)),o("p",null,[r[6]||(r[6]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/22/12/linux-file-manager-konqueror"},{default:i(()=>[...r[5]||(r[5]=[e("https://opensource.com/article/22/12/linux-file-manager-konqueror",-1)])]),_:1})]),o("p",null,[r[11]||(r[11]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/seth"},{default:i(()=>[...r[7]||(r[7]=[e("Seth Kenlon",-1)])]),_:1}),r[12]||(r[12]=e(" 選題：",-1)),n(t,{href:"https://github.com/lkxed"},{default:i(()=>[...r[8]||(r[8]=[e("lkxed",-1)])]),_:1}),r[13]||(r[13]=e(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:i(()=>[...r[9]||(r[9]=[e("geekpi",-1)])]),_:1}),r[14]||(r[14]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...r[10]||(r[10]=[e("wxy",-1)])]),_:1})]),o("p",null,[r[17]||(r[17]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...r[15]||(r[15]=[e("LCTT",-1)])]),_:1}),r[18]||(r[18]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...r[16]||(r[16]=[e("Linux中國",-1)])]),_:1}),r[19]||(r[19]=e(" 榮譽推出",-1))])])}const K=a(d,[["render",m]]);export{y as __pageData,K as default};
